import{_ as r,o as e,c as a,a2 as l}from"./chunks/framework.BXzK3EA4.js";const c=JSON.parse('{"title":"레퍼런스 게임 메커니즘 데이터베이스","description":"","frontmatter":{},"headers":[],"relativePath":"rules/Ref-Mechanism-Index.md","filePath":"rules/Ref-Mechanism-Index.md"}'),o={name:"rules/Ref-Mechanism-Index.md"};function i(n,t,s,d,u,h){return e(),a("div",null,[...t[0]||(t[0]=[l('<div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p></p></div><blockquote><p>출처 인계: <a href="https://github.com/islee23520/seoul-kenshi/blob/docs/reference-context-sync-st_01a079f1/.omo/research/README.md" target="_blank" rel="noreferrer">공유 조사 색인</a>. 로컬 sources.json·원문 패킷 언급은 조사 당시 기록이며 이 전달에 원시 자료가 포함된다는 뜻이 아니다. 누락된 ID는 미확인으로 남긴다. 자동 생성 문서입니다 — 원본은 저장소 내부 조사 문서(<code>Reference-Game-Mechanisms.md</code>)에서 파생했으며 금지 용어는 위키 공개 기준에 맞게 치환했다.</p></blockquote><h1 id="레퍼런스-게임-메커니즘-데이터베이스" tabindex="-1">레퍼런스 게임 메커니즘 데이터베이스 <a class="header-anchor" href="#레퍼런스-게임-메커니즘-데이터베이스" aria-label="Permalink to &quot;레퍼런스 게임 메커니즘 데이터베이스&quot;">​</a></h1><blockquote><p>이 문서는 게임 설계의 <strong>근거 원천</strong>이다. 레퍼런스 게임들의 위키·매뉴얼·개발자 블로그에서 확인된 메커니즘을 원문 인용과 함께 정리하고, 각 게임 로직 문서가 어떤 레퍼런스에서 어떤 규칙을 채택했는지 추적 가능하게 한다. 이 문서의 S-ID는 조사별 출처 색인을 사용하며 기존 Research-Sources 목록과는 별개다.</p></blockquote><h2 id="사용법" tabindex="-1">사용법 <a class="header-anchor" href="#사용법" aria-label="Permalink to &quot;사용법&quot;">​</a></h2><ul><li>각 섹션은 <strong>게임 → 메커니즘 → 원문 근거 → 잔선 채택</strong> 구조</li><li>게임 로직 문서(Campaign-Loop.md 등)에서 이 문서를 인용할 때는 <code>[REF:게임명-메커니즘]</code> 형식</li><li>새 조사 결과가 나오면 해당 게임 섹션에 추가 (append-only)</li><li><strong>조합 규칙</strong>: 여러 게임에서 같은 문제에 대한 다른 해법이 있으면 &quot;선택지&quot;로 병기하고 잔선의 선택 이유를 명시</li></ul><hr><h2 id="_1-켄시-k-시스템-—-떠돌이-생존과-정착-진행" tabindex="-1">1. 켄시 (K-시스템) — 떠돌이 생존과 정착 진행 <a class="header-anchor" href="#_1-켄시-k-시스템-—-떠돌이-생존과-정착-진행" aria-label="Permalink to &quot;1. 켄시 (K-시스템) — 떠돌이 생존과 정착 진행&quot;">​</a></h2><blockquote><p>공개 위키 금지 용어이므로 내부 설계에서만 &quot;K-시스템&quot;으로 지칭. 상세: 내부 종합 조사 문서 §I.</p></blockquote><h3 id="_1-1-시작-조건-ref-k-start" tabindex="-1">1.1 시작 조건 [REF:K-START] <a class="header-anchor" href="#_1-1-시작-조건-ref-k-start" aria-label="Permalink to &quot;1.1 시작 조건 [REF:K-START]&quot;">​</a></h3><ul><li><strong>13개 시작 시나리오</strong>: 각각 다른 &quot;결핍&quot; 조합 — 인원 부족/자금 부족/장비 부족/세력 관계 부족. 빈곤은 하나의 난이도가 아니라 여러 종류의 결핍이다.</li><li><strong>플레이어 세력은 시작부터 존재</strong>: <code>Nameless</code>라는 세력명으로, 정착 전부터 정치적 행위자. &quot;정착해야 세력이 된다&quot;가 아님.</li><li><strong>&quot;너는 특별하지 않다&quot;</strong>: 세계는 플레이어 없이도 돌아감. 적도 서로 싸운다.</li><li><strong>잔선 채택</strong>: Game-Thesis.md &quot;무명 인물&quot; 채택. <strong>추가 설계</strong>: 시작 시나리오 다양화(결핍 축별 분화).</li></ul><h3 id="_1-2-생존-압박-ref-k-survival" tabindex="-1">1.2 생존 압박 [REF:K-SURVIVAL] <a class="header-anchor" href="#_1-2-생존-압박-ref-k-survival" aria-label="Permalink to &quot;1.2 생존 압박 [REF:K-SURVIVAL]&quot;">​</a></h3><ul><li><strong>신체</strong>: 부위별 체력. 팔/다리 절단 가능. 치료에는 시간+의료품. 회복 가능한 실패를 고르는 것이 초반의 기술.</li><li><strong>식량</strong>: 캐릭터별 허기. 방치 시 쓰러짐 → 방치 지속 시 사망.</li><li><strong>패배 ≠ 게임오버</strong>: 죽는 대신 노예로 팔리거나 강도에게 약탈당하고 살아남음. 실패 후 재기가 핵심 루프.</li><li><strong>잔선 채택</strong>: 부상 시스템(&quot;중상→HP 감소&quot;)은 채택. 패배 시 노예/약탈은 비목표이나 &quot;패배 후 재기&quot; 정신은 채택.</li></ul><h3 id="_1-3-떠돌이→정착-ref-k-settlement" tabindex="-1">1.3 떠돌이→정착 [REF:K-SETTLEMENT] <a class="header-anchor" href="#_1-3-떠돌이→정착-ref-k-settlement" aria-label="Permalink to &quot;1.3 떠돌이→정착 [REF:K-SETTLEMENT]&quot;">​</a></h3><ul><li><strong>세 가지 상태</strong>: ①완전 유랑(야영) ②도시 내 집(임시 거점) ③야외 전초기지(생산 거점). 각각 다른 이벤트 조건.</li><li><strong>정착 시점</strong>: 날짜가 아니라 준비(연구·자재)와 욕구(생산 필요성)가 결정.</li><li><strong>정착 후</strong>: 외교·침공·세금 발생. 권리도 늘지만 책임도 늘음.</li><li><strong>잔선 채택</strong>: <code>떠돌이 → 시설 이용권 보유 → 선택적 역 운영자</code> 3단계. <strong>정착은 필수 승급이 아님.</strong></li></ul><h3 id="_1-4-무소속-경제-ref-k-nomad" tabindex="-1">1.4 무소속 경제 [REF:K-NOMAD] <a class="header-anchor" href="#_1-4-무소속-경제-ref-k-nomad" aria-label="Permalink to &quot;1.4 무소속 경제 [REF:K-NOMAD]&quot;">​</a></h3><ul><li><strong>유랑자도 정치적 행위자</strong>: 세력 관계·평판이 존재. 도시에서 쫓겨나지 않음(범죄 시 제외).</li><li><strong>경제원</strong>: 약탈·상인·의뢰·채굴. 기지 없이도 기술 습득 가능(책+연구 벤치 이용).</li><li><strong>잔선 채택</strong>: &quot;고정 거점이 없어도 준비/회복/정산 가능&quot; — 시설 이용권 개념으로 해결.</li></ul><h3 id="_1-5-무에서-시작-이-재미있는-이유-ref-k-why-fun" tabindex="-1">1.5 &quot;무에서 시작&quot;이 재미있는 이유 [REF:K-WHY-FUN] <a class="header-anchor" href="#_1-5-무에서-시작-이-재미있는-이유-ref-k-why-fun" aria-label="Permalink to &quot;1.5 &quot;무에서 시작&quot;이 재미있는 이유 [REF:K-WHY-FUN]&quot;">​</a></h3><ul><li><strong>자발적 목표 생성</strong>: 튜토리얼 목표가 아니라 &quot;배고프다→식량→돈→일거리&quot;의 자연스러운 욕구 체인.</li><li><strong>실패 지점</strong>: 초반 정보 부족으로 어디서 무엇을 해야 할지 모르는 것. 지속적 위협으로 휴식 없는 게임.</li><li><strong>잔선</strong>: 의뢰 게시판이 욕구 체인의 시작점. 지속 위협은 원정/거점 왕복 리듬으로 완화.</li></ul><h2 id="_2-배틀-브라더즈-battle-brothers-—-용병회사-경제와-진화" tabindex="-1">2. 배틀 브라더즈 (Battle Brothers) — 용병회사 경제와 진화 <a class="header-anchor" href="#_2-배틀-브라더즈-battle-brothers-—-용병회사-경제와-진화" aria-label="Permalink to &quot;2. 배틀 브라더즈 (Battle Brothers) — 용병회사 경제와 진화&quot;">​</a></h2><blockquote><p>상세: 내부 종합 조사 문서 §II.</p></blockquote><h3 id="_2-1-출신-origins-ref-bb-origins" tabindex="-1">2.1 출신(Origins) [REF:BB-ORIGINS] <a class="header-anchor" href="#_2-1-출신-origins-ref-bb-origins" aria-label="Permalink to &quot;2.1 출신(Origins) [REF:BB-ORIGINS]&quot;">​</a></h3><ul><li><strong>15개 기원</strong>: 각각 시작 보너스가 아니라 <strong>회사의 장기 규칙</strong>(고용 한계, 시작 장비, 특수 능력). <code>Sellsword</code>는 독립 기원이 아님.</li><li><strong>잔선</strong>: 시작 시나리오를 &quot;결핍 축&quot;으로 다양화 시 참조.</li></ul><h3 id="_2-2-경제-압박-루프-ref-bb-economy" tabindex="-1">2.2 경제 압박 루프 [REF:BB-ECONOMY] <a class="header-anchor" href="#_2-2-경제-압박-루프-ref-bb-economy" aria-label="Permalink to &quot;2.2 경제 압박 루프 [REF:BB-ECONOMY]&quot;">​</a></h3><ul><li><strong>일급(Wages)</strong>: 매일 크라운 지급. 못 주면 사기 하락 → 이탈. <strong>돈이 자유를 사고, 자유를 유지하려면 다시 벌어야 함.</strong></li><li><strong>식량</strong>: 매일 소모. 종류별 부패 속도 존재.</li><li><strong>수리·의약·탄약</strong>: 장비 유지 비용이 지속적 압박.</li><li><strong>잔선 채택</strong>: 보급 시스템. <strong>차이</strong>: 잔선은 화폐가 아니라 소모품. &quot;매 원정 시 소모되는 압박&quot;은 동일.</li></ul><h3 id="_2-3-로스터-배치-ref-bb-roster" tabindex="-1">2.3 로스터 ≠ 배치 [REF:BB-ROSTER] <a class="header-anchor" href="#_2-3-로스터-배치-ref-bb-roster" aria-label="Permalink to &quot;2.3 로스터 ≠ 배치 [REF:BB-ROSTER]&quot;">​</a></h3><ul><li><strong>로스터</strong>: 전체 소대원(성장 가능). <strong>배치</strong>: 전투 투입 인원.</li><li><strong>부상자 교체</strong>: 부상자는 로스터에서 쉬고 예비 인원이 대신 출전.</li><li><strong>잔선 채택</strong>: POC 적용 제안 — &quot;로스터 상한 6, 배치 상한 3, 부상자는 교체 휴식&quot;</li></ul><h3 id="_2-4-세계-진화·위기-ref-bb-crises" tabindex="-1">2.4 세계 진화·위기 [REF:BB-CRISES] <a class="header-anchor" href="#_2-4-세계-진화·위기-ref-bb-crises" aria-label="Permalink to &quot;2.4 세계 진화·위기 [REF:BB-CRISES]&quot;">​</a></h3><ul><li><strong>4종 위기</strong>: 귀족 전쟁·언데드 침공·오크 침공·성전(Holy War, Blazing Deserts). 위기는 배경이 아니라 <strong>고용 시장과 보급망의 변화</strong>.</li><li><strong>계약 유형 변화</strong>: 위기 중에는 특정 계약 증가/감소.</li><li><strong>미시적 세계 변화</strong>: 정착지 상태(파괴/점령/해방)가 개별 정착지 단위에서 일어남.</li><li><strong>잔선 채택</strong>: Campaign-Progression.md 위기 시스템. <strong>설계 필요</strong>: 위기 종류·트리거·3역 범위에서의 최소 구현.</li></ul><h3 id="_2-5-정착지-ref-bb-settlements" tabindex="-1">2.5 정착지 [REF:BB-SETTLEMENTS] <a class="header-anchor" href="#_2-5-정착지-ref-bb-settlements" aria-label="Permalink to &quot;2.5 정착지 [REF:BB-SETTLEMENTS]&quot;">​</a></h3><ul><li><strong>도시</strong>: 대형. 시장·무기고·훈련소·신전. <strong>마을</strong>: 소형. 기본 시장. <strong>요새</strong>: 군사. 병영.</li><li><strong>남의 도시를 연결해 자기 기반으로 씀</strong>: 정착하지 않아도 정착지 네트워크가 회사의 기반.</li><li><strong>잔선 채택</strong>: 역별 시설 차등. <strong>설계 필요</strong>: 3역 각각의 시설 목록.</li></ul><h3 id="_2-6-수행단-retinue-ref-bb-retinue" tabindex="-1">2.6 수행단(Retinue) [REF:BB-RETINUE] <a class="header-anchor" href="#_2-6-수행단-retinue-ref-bb-retinue" aria-label="Permalink to &quot;2.6 수행단(Retinue) [REF:BB-RETINUE]&quot;">​</a></h3><ul><li><strong>18명 비전투 수행원</strong>: 건물 없이 회사가 발전하는 방법. 상인·정찰병·재단사 등.</li><li><strong>잔선 채택</strong>: 향후 검토 — 전투원 아닌 지원 인력 시스템.</li></ul><h3 id="_2-7-지형-비용-ref-bb-terrain" tabindex="-1">2.7 지형 비용 [REF:BB-TERRAIN] <a class="header-anchor" href="#_2-7-지형-비용-ref-bb-terrain" aria-label="Permalink to &quot;2.7 지형 비용 [REF:BB-TERRAIN]&quot;">​</a></h3><ul><li><strong>이동 AP</strong>: 평지 2AP, 험지 3AP, 늪 4AP, 고도 변화 +1AP.</li><li><strong>잔선 채택</strong>: 하이트맵 Core 규칙에 반영.</li></ul><h2 id="_3-크루세이더-킹즈-3-ck3-—-인물-중심-대전략" tabindex="-1">3. 크루세이더 킹즈 3 (CK3) — 인물 중심 대전략 <a class="header-anchor" href="#_3-크루세이더-킹즈-3-ck3-—-인물-중심-대전략" aria-label="Permalink to &quot;3. 크루세이더 킹즈 3 (CK3) — 인물 중심 대전략&quot;">​</a></h2><h3 id="_3-1-인물-존재감-ref-ck3-character" tabindex="-1">3.1 인물 존재감 [REF:CK3-CHARACTER] <a class="header-anchor" href="#_3-1-인물-존재감-ref-ck3-character" aria-label="Permalink to &quot;3.1 인물 존재감 [REF:CK3-CHARACTER]&quot;">​</a></h3><ul><li><strong>상시 초상</strong>: 상단 바에 항상 초상·특성·스트레스·자원 표시.</li><li><strong>인물 카드</strong>: 특성 툴팁, 의견, 관계, 비밀.</li><li><strong>잔선 채택</strong>: POC 화면 3(거점 허브)의 파티 스트립 + 관계 패널이 이에 해당.</li></ul><h3 id="_3-2-선택-투명성-ref-ck3-choices" tabindex="-1">3.2 선택 투명성 [REF:CK3-CHOICES] <a class="header-anchor" href="#_3-2-선택-투명성-ref-ck3-choices" aria-label="Permalink to &quot;3.2 선택 투명성 [REF:CK3-CHOICES]&quot;">​</a></h3><ul><li><strong>이벤트 옵션</strong>: 각 선택지에 비용/효과/확률 사전 표시. Will Happen / Has Happened 구분.</li><li><strong>중첩 툴팁</strong>: 값 위에 커서 → 그 값의 계산 근거 툴팁 (왜 이 값인가?).</li><li><strong>잔선 채택</strong>: 조우 화면 7의 3선택(비용/효과/위험) + &quot;왜 불가?&quot; 툴팁이 이에 해당.</li></ul><h3 id="_3-3-지도-정보-모드-ref-ck3-mapmode" tabindex="-1">3.3 지도 정보 모드 [REF:CK3-MAPMODE] <a class="header-anchor" href="#_3-3-지도-정보-모드-ref-ck3-mapmode" aria-label="Permalink to &quot;3.3 지도 정보 모드 [REF:CK3-MAPMODE]&quot;">​</a></h3><ul><li><strong>지도 모드</strong>: 영토/외교/종교/문화 등 정보별 색상 전환.</li><li><strong>잔선 채택</strong>: 전략 노선도 S의 &quot;정보 모드&quot; — 세력권/통행권/위협도 표시 전환.</li></ul><h3 id="_3-4-경고-현안-시스템-ref-ck3-alerts" tabindex="-1">3.4 경고/현안 시스템 [REF:CK3-ALERTS] <a class="header-anchor" href="#_3-4-경고-현안-시스템-ref-ck3-alerts" aria-label="Permalink to &quot;3.4 경고/현안 시스템 [REF:CK3-ALERTS]&quot;">​</a></h3><ul><li><strong>차단 경고</strong>: 행동 불가 시 버튼 옆 붉은 표시.</li><li><strong>비차단 현안</strong>: &quot;주의 N&quot; 목록. 오래된 경고 자동 소멸.</li><li><strong>잔선 채택</strong>: 거점 허브의 &quot;주의 1 · 서하늘 부상&quot; 배지가 이에 해당.</li></ul><hr><h2 id="_4-파랜드-택틱스·창세기전-—-한국식-전술-srpg" tabindex="-1">4. 파랜드 택틱스·창세기전 — 한국식 전술 SRPG <a class="header-anchor" href="#_4-파랜드-택틱스·창세기전-—-한국식-전술-srpg" aria-label="Permalink to &quot;4. 파랜드 택틱스·창세기전 — 한국식 전술 SRPG&quot;">​</a></h2><h3 id="_4-1-스테이지-진행-파랜드-1-ref-ft-stage" tabindex="-1">4.1 스테이지 진행 (파랜드 1) [REF:FT-STAGE] <a class="header-anchor" href="#_4-1-스테이지-진행-파랜드-1-ref-ft-stage" aria-label="Permalink to &quot;4.1 스테이지 진행 (파랜드 1) [REF:FT-STAGE]&quot;">​</a></h3><ul><li><strong>선형 스테이지</strong>: 자유 월드맵 없음. 이야기 연결로 진행.</li><li><strong>잔선</strong>: 비채택 (잔선은 자유 이동 추구). 단, 원정의 &quot;목적&quot;이 스토리와 연결되는 구조는 참조.</li></ul><h3 id="_4-2-마을-거점-파랜드-2-ref-ft-town" tabindex="-1">4.2 마을 거점 (파랜드 2) [REF:FT-TOWN] <a class="header-anchor" href="#_4-2-마을-거점-파랜드-2-ref-ft-town" aria-label="Permalink to &quot;4.2 마을 거점 (파랜드 2) [REF:FT-TOWN]&quot;">​</a></h3><ul><li><strong>클릭 가능한 도시 지도</strong>: 시설 선택(상점/여관/훈련소)이 있는 도시 화면.</li><li><strong>잔선 채택</strong>: 거점 허브의 &quot;시설 선택&quot; 구조가 이에 해당. 단, 도시 보행은 비채택.</li></ul><h3 id="_4-3-인터미션-창세기전-ref-wog-intermission" tabindex="-1">4.3 인터미션 (창세기전) [REF:WOG-INTERMISSION] <a class="header-anchor" href="#_4-3-인터미션-창세기전-ref-wog-intermission" aria-label="Permalink to &quot;4.3 인터미션 (창세기전) [REF:WOG-INTERMISSION]&quot;">​</a></h3><ul><li><strong>인터미션 화면</strong>: 클래스·스킬·아이템 세팅. 대화 이벤트.</li><li><strong>인물 중심 대화</strong>: 키워드 선택으로 정보 획득.</li><li><strong>잔선 채택</strong>: 거점 허브의 &quot;대화&quot; + &quot;장비&quot; 기능이 이에 해당.</li></ul><hr><h2 id="_5-fire-emblem·fft-—-전술-전투-문법" tabindex="-1">5. Fire Emblem·FFT — 전술 전투 문법 <a class="header-anchor" href="#_5-fire-emblem·fft-—-전술-전투-문법" aria-label="Permalink to &quot;5. Fire Emblem·FFT — 전술 전투 문법&quot;">​</a></h2><h3 id="_5-1-수동-전술-명령-ref-fe-command" tabindex="-1">5.1 수동 전술 명령 [REF:FE-COMMAND] <a class="header-anchor" href="#_5-1-수동-전술-명령-ref-fe-command" aria-label="Permalink to &quot;5.1 수동 전술 명령 [REF:FE-COMMAND]&quot;">​</a></h3><ul><li><strong>유닛→명령→대상→확정/취소</strong>: 이동 범위 표시→칸 선택→행동 메뉴→공격 예상→확정.</li><li><strong>취소 무소모</strong>: 미리보기 중 상태 변화 없음.</li><li><strong>잔선 채택</strong>: POC 화면 9(전투)의 이동/공격/대기 + 공격 예상 + 취소가 이에 해당.</li></ul><h3 id="_5-2-페이즈-vs-ct-ref-fft-ct" tabindex="-1">5.2 페이즈 vs CT [REF:FFT-CT] <a class="header-anchor" href="#_5-2-페이즈-vs-ct-ref-fft-ct" aria-label="Permalink to &quot;5.2 페이즈 vs CT [REF:FFT-CT]&quot;">​</a></h3><ul><li><strong>FE</strong>: 아군 페이즈 → 적군 페이즈. 전체 순서가 예측 가능.</li><li><strong>FFT</strong>: CT(차지 타임) 게이지 → 개인 순서. 속도가 빠르면 더 자주 행동.</li><li><strong>잔선</strong>: <strong>선택지로 병기</strong> — POC는 단순 교대 순서를 채택했으나, CT 시스템은 성장 시스템과 연결할 때 재검토.</li></ul><h3 id="_5-3-높이와-지형-ref-fft-height" tabindex="-1">5.3 높이와 지형 [REF:FFT-HEIGHT] <a class="header-anchor" href="#_5-3-높이와-지형-ref-fft-height" aria-label="Permalink to &quot;5.3 높이와 지형 [REF:FFT-HEIGHT]&quot;">​</a></h3><ul><li><strong>FFT</strong>: 맵에 높이 존재. 높이 차이가 사거리·명중·이동에 영향.</li><li><strong>Triangle</strong>: 위협 칸 표시, 지형 효과(불·얼음·물), 고지 이점.</li><li><strong>잔선 채택</strong>: 하이트맵 B1/B2 + 층내 고저차가 이에 해당.</li></ul><hr><h2 id="_6-triangle-strategy-—-선택과-신념" tabindex="-1">6. Triangle Strategy — 선택과 신념 <a class="header-anchor" href="#_6-triangle-strategy-—-선택과-신념" aria-label="Permalink to &quot;6. Triangle Strategy — 선택과 신념&quot;">​</a></h2><h3 id="_6-1-설득·투표-ref-ts-vote" tabindex="-1">6.1 설득·투표 [REF:TS-VOTE] <a class="header-anchor" href="#_6-1-설득·투표-ref-ts-vote" aria-label="Permalink to &quot;6.1 설득·투표 [REF:TS-VOTE]&quot;">​</a></h3><ul><li><strong>정보 수집 → 설득 → 투표</strong>: 대화 전에 정보를 모아야 설득 성공률 상승.</li><li><strong>신념 시스템</strong>: 선택이 신념(자유/도덕/실용)에 누적 → 대화 옵션 해금.</li><li><strong>잔선 채택</strong>: 조우 선택이 관계·평판에 누적되는 구조가 이에 해당. 신념 시스템은 향후 검토.</li></ul><hr><h2 id="_7-잔선-설계에서-아직-답하지-않은-질문" tabindex="-1">7. 잔선 설계에서 아직 답하지 않은 질문 <a class="header-anchor" href="#_7-잔선-설계에서-아직-답하지-않은-질문" aria-label="Permalink to &quot;7. 잔선 설계에서 아직 답하지 않은 질문&quot;">​</a></h2><p>이 목록은 레퍼런스 조사에서 발견되었지만 아직 잔선 설계에 반영되지 않은 것이다.</p><table tabindex="0"><thead><tr><th>질문</th><th>레퍼런스 근거</th><th>우선순위</th></tr></thead><tbody><tr><td><s>떠돌이 시작 시나리오</s> → <strong>해결</strong>: <code>떠돌이→시설 이용권→선택적 역 운영자</code> 3단계. 시작은 남의 역에서 하룻밤을 허락받은 3인.</td><td>K-시스템 3상태 + BB 비정착 회사</td><td>해결</td></tr><tr><td><s>정착 트리거</s> → <strong>해결</strong>: 준비(자재·인력)와 욕구(생산 필요성)가 충족될 때 선택. 3역 비웠다고 역장이 되는 것 아님.</td><td>K-시스템 &quot;날짜가 아니라 준비와 욕구&quot;</td><td>해결</td></tr><tr><td><strong>출신 선택</strong>: BB의 Origins처럼 시작 조건을 플레이어가 고르는가?</td><td>BB 출신</td><td>P1</td></tr><tr><td><strong>일급 압박</strong>: BB의 일급처럼 매일 소모되는 압박이 잔선의 보급 소모인가? 구체적 수치?</td><td>BB 경제</td><td>P1</td></tr><tr><td><strong>세계 위기</strong>: BB의 위기처럼 중반에 세계 이벤트가 발생하는가? 종류?</td><td>BB 위기</td><td>P1</td></tr><tr><td><strong>역별 시설</strong>: 각 역에 어떤 시설이 있는가? 도시/마을/요새 구분?</td><td>BB 정착지</td><td>P1</td></tr><tr><td><strong>CT vs 페이즈</strong>: 전투 순서 시스템의 최종 결정</td><td>FE vs FFT</td><td>P2</td></tr><tr><td><strong>신념 시스템</strong>: Triangle의 신념 누적을 채택하는가?</td><td>TS 신념</td><td>P2</td></tr></tbody></table><hr><hr><h2 id="_8-유니콘-오버로드-unicorn-overlord-—-전투를-수행할-부대를-설계한다" tabindex="-1">8. 유니콘 오버로드 (Unicorn Overlord) — 전투를 수행할 부대를 설계한다 <a class="header-anchor" href="#_8-유니콘-오버로드-unicorn-overlord-—-전투를-수행할-부대를-설계한다" aria-label="Permalink to &quot;8. 유니콘 오버로드 (Unicorn Overlord) — 전투를 수행할 부대를 설계한다&quot;">​</a></h2><blockquote><p>2024 본편. 상세 연구: <code>.omo/evidence/gameplay-rubric-6d3fe97/ui-reference/extended-refs-structure.md</code> §8. 아래 §8-12는 [문서] 직접 열람 자료 / [추론] 구조 해석 / [적용 제안] 미구현 잔선 설계를 구분한다. [관찰]에 해당하는 직접 게임 실행·영상 검증은 하지 않았다. 출처 S140-S165는 <code>sources.json</code>에 연결된다.</p></blockquote><h3 id="_8-1-필드·작전·교전-ref-uo-maps" tabindex="-1">8.1 필드·작전·교전 [REF:UO-MAPS] <a class="header-anchor" href="#_8-1-필드·작전·교전-ref-uo-maps" aria-label="Permalink to &quot;8.1 필드·작전·교전 [REF:UO-MAPS]&quot;">​</a></h3><ul><li>[문서] 어레인으로 탐색·대화·채집하는 필드, 여러 부대를 실시간/일시정지로 지휘하는 스테이지, 접촉 후 사전 작전대로 자동 진행되는 교전이 연결된다. 필드에도 낮·밤 시계가 있고, 스테이지는 제한시간과 본거지 방어를 갖는다. [S140; S141 pp.12,16,28,37]</li><li>[추론] 이동 명령을 내리는 지도는 여행/작전 2종, 교전 표현까지 포함하면 3개 기능 표면이다. 국가 5개나 스테이지 총수를 지도 종류 수와 혼동하지 않는다. [S140-S141]</li><li>[적용 제안] 잔선의 여행→전투→정산 왕복을 강화하되 별도의 자동 교전 화면을 추가할 필요는 없다. [S141; S165]</li></ul><h3 id="_8-2-브레이브·훈장·명성의-분리-ref-uo-resources" tabindex="-1">8.2 브레이브·훈장·명성의 분리 [REF:UO-RESOURCES] <a class="header-anchor" href="#_8-2-브레이브·훈장·명성의-분리-ref-uo-resources" aria-label="Permalink to &quot;8.2 브레이브·훈장·명성의 분리 [REF:UO-RESOURCES]&quot;">​</a></h3><ul><li>[문서] 브레이브(Valor)는 전장 적 격파·시설 해방 등으로 얻고 출격·전장 스킬에 쓴다. 훈장(Honors)은 퀘스트/납품에서 얻어 고용·편성 확충·승급에 쓰며, 명성(Renown)은 랭크에 따라 기능을 해금한다. 서로 다른 자원이다. [S141 pp.18,21,28,30]</li><li>[문서] AP는 교전 중 능동 스킬, PP는 조건부 반응 스킬에 사용한다. 스태미나는 교전 후 작전 지속성에 관여하며 0일 때 이동이 불가능하다. 한국 위키의 &#39;0이면 무방비&#39; 문장은 같은 문서의 정정과 충돌하므로 휴식 중 무방비와 동일시하지 않는다. [S141 pp.28,37; S142 §7.4/§8]</li><li>[적용 제안] 전투 AP, 하루 보급, 조직 성장 자격을 하나의 추상 자원으로 합치지 않는다. 다만 원작 자원 종류를 모두 잔선에 추가하지도 않는다. [S141; S165]</li></ul><h3 id="_8-3-6칸에-최대-5명-역할·표적·순서-ref-uo-formation" tabindex="-1">8.3 6칸에 최대 5명: 역할·표적·순서 [REF:UO-FORMATION] <a class="header-anchor" href="#_8-3-6칸에-최대-5명-역할·표적·순서-ref-uo-formation" aria-label="Permalink to &quot;8.3 6칸에 최대 5명: 역할·표적·순서 [REF:UO-FORMATION]&quot;">​</a></h3><ul><li>[문서] 전열 3칸+후열 3칸, 정원은 확충되며 최대 5명이다. 초반 2인 부대도 있고 최대 5인×10부대를 편성한다. 리더는 이동 타입·스태미나·리더 효과를, 구성원 전체는 이동속도 산정에 영향을 준다. [S141 pp.21,23]</li><li>[문서] 전열은 후열에 대한 일반 직접 공격을 막지만 원거리·마법·관통 예외가 있다. 전후열 자체가 일괄 피해감소 보너스는 아니다. 관통을 피하려면 전후열 같은 선상 배치를 피한다. [S141 pp.39-40]</li><li>[문서] 장비도 스킬을 추가하며 작전 우선순위·조건과 AP/PP 잔량이 행동을 결정한다. 전멸하지 않고 양측 AP가 소진되면 잔여 HP의 <strong>비율</strong>로 승패를 정한다. 단순 HP 절대합이 아니다. [S140; S141 pp.24,37-38; S142 §8]</li><li>[추론] &#39;탱커·딜러·힐러 한 명씩&#39;보다 어느 적을 상대하고 어떤 반응 예산을 남길지 설계하는 게임이다. FE/FFT의 이번 행동 결정을 교전 이전의 편성·규칙으로 옮겼다. Ogre Battle/FFXII의 계보를 결합한 것이지 세계 최초 자동 부대 전투는 아니다. [S01-S02; S141-S143]</li><li>[적용 제안] 잔선은 수동 SRPG를 유지하면서 역할 상성·지원 관계·출격 전 비교를 차용한다. [S165]</li></ul><h3 id="_8-4-해방→복구→자원-회수-ref-uo-liberation" tabindex="-1">8.4 해방→복구→자원 회수 [REF:UO-LIBERATION] <a class="header-anchor" href="#_8-4-해방→복구→자원-회수-ref-uo-liberation" aria-label="Permalink to &quot;8.4 해방→복구→자원 회수 [REF:UO-LIBERATION]&quot;">​</a></h3><ul><li>[문서] 해방 후 시설을 이용하고 채집품 납품으로 복구한다. 수비병 지정 시 이후 스테이지 완료마다 자금·주변 채집품을 받는다. 수비병으로 둔 인물도 출격할 수 있다. [S141 pp.18,20]</li><li>[추론] 수비병은 신생/삼국지의 전담 행정 인력과 같은 기회비용이 아니다. 해방이 곧 자율 국가 전쟁·세금 경영을 뜻하지 않는다. [S141 p.20; S142 §7.1]</li><li>[적용 제안] 역 해방과 시설 재가동을 분리하되, 잔선은 현지 담당자의 원정 부재가 운영에 미치는 영향을 별도로 설계한다. [S165]</li></ul><h3 id="_8-5-조건부-모집-ref-uo-recruit" tabindex="-1">8.5 조건부 모집 [REF:UO-RECRUIT] <a class="header-anchor" href="#_8-5-조건부-모집-ref-uo-recruit" aria-label="Permalink to &quot;8.5 조건부 모집 [REF:UO-RECRUIT]&quot;">​</a></h3><ul><li>[문서] 공식은 60명 이상의 고유 인물을 설명한다. 스토리 동행, 서브퀘스트, 특정 인물의 전장 대화, 과거 처분의 지연 효과, 투기장 도전, 별도의 범용 용병 고용을 구별한다. [S140-S144]</li><li>[문서] 힐다는 프림과 전장 대화 후 완료·필드 수락이 필요하고, 가멜은 초반 석방 여부가 후반 합류에 영향을 준다. 리뷰 64명/위키 최대71명은 집계 범위 차이로 기록하며 전수 영입 수를 확정하지 않는다. [S142-S144]</li><li>[적용 제안] 인물 합류를 전리품처럼 자동 지급하지 말고 관계·이전 선택·임무에 연결한다. [S144; S165]</li></ul><h2 id="_9-배너로드-mount-blade-2-—-같은-클랜의-정치적-자격-변화" tabindex="-1">9. 배너로드 (Mount &amp; Blade 2) — 같은 클랜의 정치적 자격 변화 <a class="header-anchor" href="#_9-배너로드-mount-blade-2-—-같은-클랜의-정치적-자격-변화" aria-label="Permalink to &quot;9. 배너로드 (Mount &amp; Blade 2) — 같은 클랜의 정치적 자격 변화&quot;">​</a></h2><blockquote><p>기본 싱글플레이 구조. War Sails/모드 제외. 출시 리뷰와 후속 공식 패치, 전용 위키를 교차 확인하며 최신 모든 퍽·일당·창건 조건을 보증하지 않는다. 상세 연구 §9. [S145-S153]</p></blockquote><h3 id="_9-1-무소속→용병→봉신→왕국-ref-mb-progression" tabindex="-1">9.1 무소속→용병→봉신→왕국 [REF:MB-PROGRESSION] <a class="header-anchor" href="#_9-1-무소속→용병→봉신→왕국-ref-mb-progression" aria-label="Permalink to &quot;9.1 무소속→용병→봉신→왕국 [REF:MB-PROGRESSION]&quot;">​</a></h3><ul><li>[문서] 클랜은 인물·가족·동료와 여러 파티를 포함하며 왕국은 여러 클랜을 포함한다. 위키상 T1/명성50에 용병, T2/명성150에 봉신 자격을 얻는다. 캠페인에는 가족·메인 퀘스트의 틀이 있고 Sandbox는 이를 생략한다. [S146-S147; S151 §5]</li><li>[문서] 용병의 영향력은 계약 수입에 연결되고 봉신은 봉토·정책·군단 동원에 참여한다. 독립 클랜의 영지 보유와 왕국 선포는 구별한다. 공식 e1.7.0 공지는 총독 대화 창건을 설명하므로 Dragon Banner 퀘스트만이 창건 방법이라는 옛 가이드는 채택하지 않는다. [S149; S152]</li><li>[추론] 이 순서는 강제 장 목록이 아니라 권한을 배우는 경로다. BB 역시 자유 샌드박스지만 지속 주체가 용병회사이며 배너로드는 클랜의 국가적 역할까지 바뀐다. [S97; S106; S146-S149]</li><li>[적용 제안] 잔선은 용역 계약→통행/보급 협약→운영 위탁→선택적 자치의 권한 전이로 번역한다. [S165]</li></ul><h3 id="_9-2-병종·급료·보급·성장-ref-mb-party" tabindex="-1">9.2 병종·급료·보급·성장 [REF:MB-PARTY] <a class="header-anchor" href="#_9-2-병종·급료·보급·성장-ref-mb-party" aria-label="Permalink to &quot;9.2 병종·급료·보급·성장 [REF:MB-PARTY]&quot;">​</a></h3><ul><li>[문서] 일반 병사 승급은 영웅의 개별 퍽 성장과 다르다. 기병 승급에는 말/전투마를 추가로 소비한다. 일급과 식량, 음식 다양성의 사기 효과, 부상·전투 도주가 원정의 부담을 만든다. [S148; S151 §3.2/§4/§5.6]</li><li>[문서] 6속성군×3기술=18기술이며 사용 경험을 쌓고 속성/집중 포인트로 학습 효율·범위를 조절한다. 기술 단계에서 퍽을 선택한다. 정찰·병참·의료·공병 담당자에게 서로 다른 역량이 필요하다. [S147-S148]</li><li>[추론] 집중 포인트는 즉시 기술 레벨을 사는 돈이 아니다. 어떤 인물을 실제 어떤 일에 배치하는지가 성장 경로다. [S148]</li><li>[적용 제안] 잔선의 전문 인력은 전투력 외에 복구·운송·의료로 파티 지속력을 바꾸어야 한다. [S165]</li></ul><h3 id="_9-3-세계-지도·봉토·군단·공성-ref-mb-kingdom" tabindex="-1">9.3 세계 지도·봉토·군단·공성 [REF:MB-KINGDOM] <a class="header-anchor" href="#_9-3-세계-지도·봉토·군단·공성-ref-mb-kingdom" aria-label="Permalink to &quot;9.3 세계 지도·봉토·군단·공성 [REF:MB-KINGDOM]&quot;">​</a></h3><ul><li>[문서/추론] 파티가 움직이는 전략/여행 통합 지도, 현지 탐색 공간, 직접 전투의 3종 기능 표면이다. 지역 상호작용은 메뉴로도 처리할 수 있다. 한국 자료는 84일/년을 설명하지만 실제 초 환산과 모든 메뉴의 자동정지 경계는 미검증이다. [S145-S146; S151 §7; S153]</li><li>[문서] 봉토는 공성 기여만으로 자동 소유되지 않고 배분 투표/군주의 결정이 개입한다. 총독·시설·식량·번영·충성·치안과 연결 마을의 안전이 중요하다. [S146; S151 §6]</li><li>[문서] 영향력으로 다른 클랜 파티를 군단에 부르고 결속을 보충한다. 자기 클랜 파티 호출은 영향력 예외다. 공성은 지도에서 캠프/장비를 준비한 뒤 성벽·문·사다리·공성 장비가 있는 직접 전투로 이어진다. [S149; S151 §4.2/§6.2]</li><li>[적용 제안] 수비 책임·동료 분산·연결 봉쇄는 참조하되 대규모 1인칭 액션 전투를 추가하지 않는다. [S165]</li></ul><h3 id="_9-4-공방과-상단-ref-mb-economy" tabindex="-1">9.4 공방과 상단 [REF:MB-ECONOMY] <a class="header-anchor" href="#_9-4-공방과-상단-ref-mb-economy" aria-label="Permalink to &quot;9.4 공방과 상단 [REF:MB-ECONOMY]&quot;">​</a></h3><ul><li>[문서] 직접 교역은 지역 가격 차를 이용한다. 공방은 원료→제품과 현지 수요/경쟁에, 상단은 실제 이동·거래·호위·포획 위험에 묶인다. 상단 일급과 거래 매출의 시점도 다르다. [S146; S150-S151]</li><li>[문서] 출시 리뷰는 공방/상단의 수익 원인 설명과 직접 운영 선택이 얕다는 한계를 지적한다. &#39;경제 기능이 있다&#39;와 &#39;모든 사업을 깊게 경영한다&#39;는 별개다. [S146]</li><li>[적용 제안] 잔선의 생산 시설/운송조는 고정 이자가 아니라 원료·노선·담당자·운영비의 손익으로 보여 준다. [S165]</li></ul><h2 id="_10-신장의야망-信長の野望-—-신생의-인사·군수와-천상기의-성장" tabindex="-1">10. 신장의야망 (信長の野望) — 신생의 인사·군수와 천상기의 성장 <a class="header-anchor" href="#_10-신장의야망-信長の野望-—-신생의-인사·군수와-천상기의-성장" aria-label="Permalink to &quot;10. 신장의야망 (信長の野望) — 신생의 인사·군수와 천상기의 성장&quot;">​</a></h2><blockquote><p>신생 2022 일본어 본편 매뉴얼을 주근거로 사용한다. 현행 영어 Awakening/PK 매뉴얼의 별도 공성·방어거점은 확장 규칙으로 분리한다. 천상기는 PC 계열이며 SFC 예외를 표시한다. 상세 연구 §10. [S154-S156]</p></blockquote><h3 id="_10-1-군·성·도로와-시간-ref-na-maps" tabindex="-1">10.1 군·성·도로와 시간 [REF:NA-MAPS] <a class="header-anchor" href="#_10-1-군·성·도로와-시간-ref-na-maps" aria-label="Permalink to &quot;10.1 군·성·도로와 시간 [REF:NA-MAPS]&quot;">​</a></h3><ul><li>[문서] 72국 아래 군이 있고, 성이 소속 군의 병력·군량 중심이 된다. 군단은 여러 성을 묶어 위임하는 조직이다. 지리 구획과 행정 조직을 같은 계층으로 취급하지 않는다. [S154 3200/4200/8500]</li><li>[문서/추론] 전국 지도에서 내정·행군·접촉전·공성, 별도 합전에서 실시간 부대/퇴로 지휘를 한다. 본편은 전략+합전 2종 지도이며 확장 공성을 소급 집계하지 않는다. [S154 3300/4100/7300/7400; S155]</li><li>[문서] 진행/정지를 조절하며 행군은 일별 군량 소비, 수입은 월초, 논공행상은 3개월마다다. 천상기의 계절 턴과 다르다. [S154 3300/7100/8600]</li></ul><h3 id="_10-2-신분과-직명·지행-ref-na-delegation" tabindex="-1">10.2 신분과 직명·지행 [REF:NA-DELEGATION] <a class="header-anchor" href="#_10-2-신분과-직명·지행-ref-na-delegation" aria-label="Permalink to &quot;10.2 신분과 직명·지행 [REF:NA-DELEGATION]&quot;">​</a></h3><ul><li>[문서] 직할지 대관, 다른 성의 영주, 성주, 군단장은 역할이 다르다. 훈공으로 오른 신분이 맡을 수 있는 자리를 해금한다. 낮은 신분은 대관에서 경험을 쌓고, 영주/성주 재배치 자유도도 제도개신 정책으로 열린다. [S154 3200/5100/8100]</li><li>[문서] 높은 신분에 낮은 자리를 주면 충성이 하락할 수 있다. 낮은 충성은 출분·성의 조기 항복·독단 철수 위험이며, 능력·상성은 개발·성 전력에 영향을 준다. 담당자가 없는 군은 개발되지 않는다. [S154 3200/4300/5100]</li><li>[추론] 영토 확대→새 자리→공신 보상→개발/전력 증가가 성장 루프다. 인재 부족은 실제 확장 병목이다. [S154 5100/8600]</li><li>[적용 제안] 역장·시설 책임자·순찰 지휘를 분리하고 담당자 공백과 위임 결과를 표시한다. [S165]</li></ul><h3 id="_10-3-경제와-전쟁-준비-ref-na-economy" tabindex="-1">10.3 경제와 전쟁 준비 [REF:NA-ECONOMY] <a class="header-anchor" href="#_10-3-경제와-전쟁-준비-ref-na-economy" aria-label="Permalink to &quot;10.3 경제와 전쟁 준비 [REF:NA-ECONOMY]&quot;">​</a></h3><ul><li>[문서] 농촌/관개→석고→군량·병력, 시장/상인 마을→금 수입이다. 금 상납과 달리 군량은 성별 재고다. 노력은 작업에 묶였다가 완료 후 회복하고 정책은 준비 기간과 월 유지비를 가진다. [S154 4100/4200/5100/8100]</li><li>[문서] 목표 지정은 영주의 내정을 중단시키고 군비 준비로 전환한다. 임전 상태는 전력·휴대 군량을 늘린다. 성하 방침의 자율 건설은 직접 건설과 속도/비용이 다르다. [S154 5300/7100]</li><li>[적용 제안] 동원 비용에 출진 시 물자뿐 아니라 중단된 생산과 현지 인력을 포함한다. [S165]</li></ul><h3 id="_10-4-부대·공성·위풍-ref-na-war" tabindex="-1">10.4 부대·공성·위풍 [REF:NA-WAR] <a class="header-anchor" href="#_10-4-부대·공성·위풍-ref-na-war" aria-label="Permalink to &quot;10.4 부대·공성·위풍 [REF:NA-WAR]&quot;">​</a></h3><ul><li>[문서] 성주와 소속 영주가 부대 능력을 형성한다. 기마/철포 LV는 시설·정책·특성에 따른 공격 효과이며 천상기의 배타적 병과 선택과 같지 않다. 도로 폭과 군량 일수가 전개를 제한한다. [S154 4200/7100]</li><li>[문서] 본편 공성은 포위/강공과 내구도 공방, 합전은 전멸 외에도 총사기·퇴로·다이묘 격파로 승리한다. 위풍은 인근 귀속·외교·충성까지 바꿀 수 있다. [S154 7200/7300/7400]</li><li>[적용 제안] 전술 결과가 인접 역의 협력/통행에 영향을 주는 인과를 참고하되 승리 한 번으로 무조건 영토 전체를 지급하지 않는다. [S165]</li></ul><h3 id="_10-5-천상기의-재능·교육·군단-ref-na-tenshoki" tabindex="-1">10.5 천상기의 재능·교육·군단 [REF:NA-TENSHOKI] <a class="header-anchor" href="#_10-5-천상기의-재능·교육·군단-ref-na-tenshoki" aria-label="Permalink to &quot;10.5 천상기의 재능·교육·군단 [REF:NA-TENSHOKI]&quot;">​</a></h3><ul><li>[문서] PC214성/SFC120성, 전략은 계절 1턴과 군단 행동력, 합전은 주변 최대9성 참여다. 정치·전투·지모의 현재 능력과 재능 한계를 분리하고 실무·교육·전쟁으로 성장시킨다. 병과 적성과 군마/철포 조달도 전력을 바꾼다. [S156 §2.1-2.5]</li><li>[문서] 1군단 외 자치·방침과 해임/해체의 충성 비용, 군단장의 독립 위험이 있다. 금·쌀·성 개발·상인 거래는 확인했지만 농업/상업의 정확한 수입 계절·산식은 미확인이다. [S156 §2.5-2.8]</li><li>[추론/적용 제안] 성장과 다성 정복의 빠른 피드백은 매력적이나 전투 성장 폭증은 비전투 인물을 무의미하게 만들 수 있다. 잔선은 현장 복구·의료·운송에도 유효한 숙련 경로를 둔다. [S156 §2.5; S165]</li></ul><h2 id="_11-태합입지전-太閤立志伝-—-생업·신분·명령권의-분리" tabindex="-1">11. 태합입지전 (太閤立志伝) — 생업·신분·명령권의 분리 <a class="header-anchor" href="#_11-태합입지전-太閤立志伝-—-생업·신분·명령권의-분리" aria-label="Permalink to &quot;11. 태합입지전 (太閤立志伝) — 생업·신분·명령권의 분리&quot;">​</a></h2><blockquote><p>5 원작2004/DX2022 중 DX 공식 매뉴얼을 기준으로 한다. 공식960명은 플레이 가능한 전체 인물 풀이지 초기 전원해금이 아니다. 상세 연구 §11. [S157-S160]</p></blockquote><h3 id="_11-1-출세는-강제-단일-트리가-아니다-ref-tr-career" tabindex="-1">11.1 출세는 강제 단일 트리가 아니다 [REF:TR-CAREER] <a class="header-anchor" href="#_11-1-출세는-강제-단일-트리가-아니다-ref-tr-career" aria-label="Permalink to &quot;11.1 출세는 강제 단일 트리가 아니다 [REF:TR-CAREER]&quot;">​</a></h3><ul><li>[문서] 히데요시의 출세가 모티프지만 무사·상인·닌자·해적과 검호·다인·의사·대장장이의 목표가 다르다. 낭인/기존 직위 인물로 시작할 수 있으며 &#39;농민→관백&#39;은 공통 레벨 트리가 아니다. [S157; S158 1200; S159 4200/5160]</li><li>[문서] 가로 이하에서는 주명을 수행하고 성주부터 직접 평정을 열어 부하에게 일을 준다. 국주는 복수 성·수송, 다이묘는 외교·정복 방향과 타 직능 세력 의뢰를 결정한다. 독립/계승은 단순 XP 자동 승급과 다르다. [S159 5100/5130/5160]</li><li>[적용 제안] 생업 숙련·조직 직위·시설 운영권을 별도 축으로 두고, 의무원이 장군이 되지 않아도 진료소 운영이라는 성취를 갖게 한다. [S165]</li></ul><h3 id="_11-2-기한과-귀환-보고-ref-tr-time" tabindex="-1">11.2 기한과 귀환 보고 [REF:TR-TIME] <a class="header-anchor" href="#_11-2-기한과-귀환-보고-ref-tr-time" aria-label="Permalink to &quot;11.2 기한과 귀환 보고 [REF:TR-TIME]&quot;">​</a></h3><ul><li>[문서] 무사 평정은 홀수 달1-5일, 임무 선택→수행→기한 내 주군 보고→훈공이다. 남는 시간에 돈벌이·사사·교류를 한다. 임무 물품 확보만으로 보고가 완료되지 않는다. [S159 5100]</li><li>[문서] 닌자/해적은 불규칙 소집 후 한 달 내 출석, 상인은 홀수 달 초 평정이다. 봉록은 월초 집 금고에 들어간다. 이동/수련/휴식이 일정의 기회비용을 만든다. [S158 3100/3200; S159 4200-4500/5200-5400]</li><li>[적용 제안] 잔선의 운송·치료·복구 의뢰는 작업 완료와 귀환 보고, 다음 업무까지의 개인 시간을 구별한다. [S165]</li></ul><h3 id="_11-3-사사·인맥·카드-ref-tr-skills" tabindex="-1">11.3 사사·인맥·카드 [REF:TR-SKILLS] <a class="header-anchor" href="#_11-3-사사·인맥·카드-ref-tr-skills" aria-label="Permalink to &quot;11.3 사사·인맥·카드 [REF:TR-SKILLS]&quot;">​</a></h3><ul><li>[문서] 5능력·16기능·6카드 범주를 구별한다. 사사는 높은 기능의 인물/시설과 관계·물품 조건에 연결되며 공식 설명상 레벨4까지 배운다. 수련/과업의 미니게임·자동 처리에는 판본 차이가 있다. [S158 3300/3400; S160 §3]</li><li>[문서] 선물·다도·대련으로 친밀해지면 취업/사사/입문/모집의 접근이 열린다. 훈공·악명·칭호·관위는 친밀도와 다른 축이다. 주인공 카드는 다음 플레이 인물 해금이며 모든 기술 카드가 다음 회차 공용 전투력은 아니다. [S158 3200/3400/3600; S159 5100/5160/5500]</li><li>[적용 제안] 교사·전문가를 찾아가는 여행과 생업 현장 실무를 성장에 연결한다. [S165]</li></ul><h3 id="_11-4-비통치-경로와-개인-서사-ref-tr-paths" tabindex="-1">11.4 비통치 경로와 개인 서사 [REF:TR-PATHS] <a class="header-anchor" href="#_11-4-비통치-경로와-개인-서사-ref-tr-paths" aria-label="Permalink to &quot;11.4 비통치 경로와 개인 서사 [REF:TR-PATHS]&quot;">​</a></h3><ul><li>[문서] 상인은 분점·판로·상업권 특권, 닌자/해적은 별도 거점·후원 다이묘·영역을 운영한다. 검호는 유파/도장/제자, 다인은 다실/다회, 의사는 약초·제약·처방·진료 평판, 대장장이는 기술 습득·원료·무구 제작을 추구한다. [S159 4300-5800]</li><li>[문서] 세력 직업과 구도 직업은 병행할 수 있으나 집에 여는 작업장은 하나다. 개인전과 합전도 별개이며 합전에서는 신분에 따라 자기 부대 또는 군단 전체를 지휘한다. [S158 1200/3500/3600]</li><li>[추론/적용 제안] &#39;어떤 사람으로 살아왔는가&#39;가 &#39;누구에게 어떤 일을 맡길 권한이 생겼는가&#39;로 이어져야 한다. 모든 성공을 군사 통일로 환산하지 않는다. [S158-S159; S165]</li></ul><h2 id="_12-삼국지-三國志-—-14의-토지·담당자·보급선" tabindex="-1">12. 삼국지 (三國志) — 14의 토지·담당자·보급선 <a class="header-anchor" href="#_12-삼국지-三國志-—-14의-토지·담당자·보급선" aria-label="Permalink to &quot;12. 삼국지 (三國志) — 14의 토지·담당자·보급선&quot;">​</a></h2><blockquote><p>2020 본편 군주제. 삼국지 8 REMAKE 등 전 무장 플레이 작품과 구별하며 &#39;2026 최신 출시작&#39;이라는 수식어를 쓰지 않는다. 상세 연구 §12-14. [S161-S164]</p></blockquote><h3 id="_12-1-군주제·hex·10일-실행-ref-rtk-maps" tabindex="-1">12.1 군주제·HEX·10일 실행 [REF:RTK-MAPS] <a class="header-anchor" href="#_12-1-군주제·hex·10일-실행-ref-rtk-maps" aria-label="Permalink to &quot;12.1 군주제·HEX·10일 실행 [REF:RTK-MAPS]&quot;">​</a></h3><ul><li>[문서] 최소 도시를 가진 세력을 고르고 HEX→지역 중심(core)→도시권을 확보한다. 군단은 여러 도시의 위임 조직이다. 도시를 모두 잃으면 세력이 붕괴한다. [S162 2400/3100/3300]</li><li>[문서/추론] 전쟁과 행정이 같은 연속 지도에서 진행된다. 전략 단계에서 명령을 정하고 진행10일→보고로 반복하며 일반 명령은 진행 중 변경할 수 없다. 월은3순, 수입은 월초, 보급은 매순이다. Adjutant로 지정된 무장의 전법 타이밍 개입은 예외로 구별한다. [S162 3200/3300/5300]</li><li>[적용 제안] 잔선의 시간 계약을 먼저 정하고 실시간 정지형·예약실행형·수동 전술 턴을 혼합하지 않는다. [S165]</li></ul><h3 id="_12-2-인재가-행정-용량이-된다-ref-rtk-officers" tabindex="-1">12.2 인재가 행정 용량이 된다 [REF:RTK-OFFICERS] <a class="header-anchor" href="#_12-2-인재가-행정-용량이-된다-ref-rtk-officers" aria-label="Permalink to &quot;12.2 인재가 행정 용량이 된다 [REF:RTK-OFFICERS]&quot;">​</a></h3><ul><li>[문서] 공식은1000+무장·150+개성, 한국자료는 기본 역사무장1000·46도시·340중요지점을 기술한다. DLC/편집/역사 집계 범위를 구분한다. [S161; S163]</li><li>[문서] 지역·징병·훈련 담당자를 임명하고 그 사람이 출진/다른 일을 하면 효과가 감소한다. 지역 무담당은 계절 개발/치안 하락을 낳는다. 통솔·무력·지력·정치·매력의 행정 용도가 다르다. [S162 4200]</li><li>[문서] 군주의 주의는 시정 부서 슬롯·비용 한도를 정하고, 배치한 무장의 정책이 다음 순부터 활성화된다. 군사에는 자격과 정책 비용 예외가 있다. [S162 4100]</li><li>[적용 제안] 유명 전투원뿐 아니라 평범한 전문 인력도 시설·지역 운영에 필요하게 만든다. [S165]</li></ul><h3 id="_12-3-개발·징병·진형·연계-ref-rtk-war" tabindex="-1">12.3 개발·징병·진형·연계 [REF:RTK-WAR] <a class="header-anchor" href="#_12-3-개발·징병·진형·연계-ref-rtk-war" aria-label="Permalink to &quot;12.3 개발·징병·진형·연계 [REF:RTK-WAR]&quot;">​</a></h3><ul><li>[문서] 지역의 상업/농업/병영 개발, 도시 모집/훈련 담당을 나눈다. 병력 증가는 소비도 늘리고, 군량 부족은 병력 이탈/사기 저하를 낳는다. [S162 4200]</li><li>[문서] 출진은 지휘관·진형·병력·전법·목표·접적/추격/퇴각 방침을 묶는다. 진형은 기동·점령 폭·부대전·공성을 구분하며 관직은 지휘 병력 상한에 연결된다. [S162 5100/6100/7100]</li><li>[문서] 좋은 관계의 지휘관이 같은 군단에서 근접하고 상태 이상이 없으면 연계 능력/전법이 강화된다. 개성은 유불리와 일부 행동 설정 제한을 만든다. 영웅은 병력 숫자 배수만이 아니다. [S162 5100]</li></ul><h3 id="_12-4-보급선과-외교의-버전-경계-ref-rtk-supply" tabindex="-1">12.4 보급선과 외교의 버전 경계 [REF:RTK-SUPPLY] <a class="header-anchor" href="#_12-4-보급선과-외교의-버전-경계-ref-rtk-supply" aria-label="Permalink to &quot;12.4 보급선과 외교의 버전 경계 [REF:RTK-SUPPLY]&quot;">​</a></h3><ul><li>[문서] 원도시와 부대를 자국/동맹 통제 토지로 연결하고 길이·험지가 소비에 영향을 준다. 차단되면 큰 사기 손실과 이동/공격 제한을 받는다. 공식은 여포/장료를 정면 대결 대신 보급 차단·시설·전법으로 상대하라고 권한다. [S162 5100/7200]</li><li>[문서] 본편 외교 목록은 친선·동맹·파기·포로 반환·공격 요청·항복 권고다. 범용 혼인동맹 명령은 확인되지 않았다. 역사 혼인/배우자 관계를 신생의 일반 혼인 외교와 혼동하지 않는다. [S162 6100; S154 6200]</li><li>[적용 제안] HEX 색칠보다 역·터널·환승 보급 연결을 참조한다. 통행·펌프·전력·의료 이송의 복구가 작전 지속력을 바꾸게 한다. [S165]</li></ul><h3 id="_12-5-5종-결합-원칙-ref-rtk-synthesis" tabindex="-1">12.5 5종 결합 원칙 [REF:RTK-SYNTHESIS] <a class="header-anchor" href="#_12-5-5종-결합-원칙-ref-rtk-synthesis" aria-label="Permalink to &quot;12.5 5종 결합 원칙 [REF:RTK-SYNTHESIS]&quot;">​</a></h3><ul><li>[추론] 유니콘은 해방에 따른 편성 선택지 확대, 배너로드는 클랜의 정치적 자격, 신생은 인사 위임, 태합입지전은 개인의 경력/권한, 삼국지14는 토지·행정·보급 연결을 성장의 중심으로 삼는다. 모두를 같은 &#39;빈손→왕&#39; 공식으로 묶을 수 없다. [S141; S146-S149; S154; S158-S159; S162]</li><li>[적용 제안] 잔선의 중심은 BB 원정 손익+K 생존/회복 지속성+태합입지전 생업/직위 분리다. 유니콘의 상성/편성, 신생의 위임, 삼국지의 연결 차단은 그 중심을 보강한다. [S84; S89; S97; S102-S104; S141; S154; S158-S159; S162]</li><li>[적용 제안] 유니콘의 &#39;수비병도 출격 가능&#39;과 신생/삼국지의 전담 인력 비용은 양립하지 않으므로 선택해야 한다. 잔선에서는 원정 시 대행 또는 운영 효율 손실을 권하며, 수치와 자격은 별도 설계다. 기존 수동 SRPG·3역×B1/B2 계약과 점령→안정화→통합 설계를 이 연구로 변경하지 않는다. [S141 p.20; S154 5300; S162 4200; S165]</li></ul><h2 id="출처-인덱스" tabindex="-1">출처 인덱스 <a class="header-anchor" href="#출처-인덱스" aria-label="Permalink to &quot;출처 인덱스&quot;">​</a></h2><p>모든 인용은 <code>.omo/evidence/gameplay-rubric-6d3fe97/ui-reference/sources.json</code>의 S-ID와 연결.</p><table tabindex="0"><thead><tr><th>접두어</th><th>게임</th><th>주요 출처</th></tr></thead><tbody><tr><td>K-</td><td>켄시</td><td>내부 원문 덤프/ wiki 덤프, RPS·PCGamer 리뷰</td></tr><tr><td>BB-</td><td>배틀 브라더즈</td><td>bb-raw/ wiki 덤프(15개 문서), dev blog</td></tr><tr><td>CK3-</td><td>크루세이더 킹즈 3</td><td>ck3-ui-reference.md, Paradox 위키, 공식 개발일지</td></tr><tr><td>FT-</td><td>파랜드 택틱스</td><td>REPORT.md S08</td></tr><tr><td>WOG-</td><td>창세기전</td><td>REPORT.md S09</td></tr><tr><td>FE-</td><td>파이어 엠블렘</td><td>REPORT.md S01 (Awakening 매뉴얼)</td></tr><tr><td>FFT-</td><td>FFT</td><td>REPORT.md S02 (PS 매뉴얼)</td></tr><tr><td>TS-</td><td>Triangle Strategy</td><td>REPORT.md S05-S07</td></tr><tr><td>UO-</td><td>유니콘 오버로드</td><td>extended-refs-structure.md §8, S140-S144</td></tr><tr><td>MB- / BL-</td><td>배너로드</td><td>extended-refs-structure.md §9, S145-S153</td></tr><tr><td>NA-</td><td>신장의야망</td><td>extended-refs-structure.md §10, S154-S156</td></tr><tr><td>TR- / TK-</td><td>태합입지전</td><td>extended-refs-structure.md §11, S157-S160</td></tr><tr><td>RTK-</td><td>삼국지</td><td>extended-refs-structure.md §12, S161-S164</td></tr></tbody></table><hr><h2 id="_13-포획과-영입-—-구금-해방-자발적-합류의-분리" tabindex="-1">13. 포획과 영입 — 구금, 해방, 자발적 합류의 분리 <a class="header-anchor" href="#_13-포획과-영입-—-구금-해방-자발적-합류의-분리" aria-label="Permalink to &quot;13. 포획과 영입 — 구금, 해방, 자발적 합류의 분리&quot;">​</a></h2><blockquote><p>조사: <code>st_01a0777a</code>, 2026-09-06. 상세: <code>.omo/evidence/gameplay-rubric-6d3fe97/ui-reference/capture-recruit-system.md</code>. 출처 S110~S129는 같은 폴더 <code>sources.json</code>에 연결된다. **[문서]**는 위키·버전 고정 코드 자료의 정적 열람, **[추론]**은 해석, **[적용 제안]**은 미구현 설계다. 원작 실행·잔선 런타임 검증은 하지 않았다. [S119, S129]</p></blockquote><h3 id="_13-1-k-시스템-포획은-조종권-획득이-아니다-ref-k-capture" tabindex="-1">13.1 K-시스템: 포획은 조종권 획득이 아니다 [REF:K-CAPTURE] <a class="header-anchor" href="#_13-1-k-시스템-포획은-조종권-획득이-아니다-ref-k-capture" aria-label="Permalink to &quot;13.1 K-시스템: 포획은 조종권 획득이 아니다 [REF:K-CAPTURE]&quot;">​</a></h3><ul><li><strong>[문서: 원문]</strong> Prisoner Cage는 &quot;first pick up the target&quot; 후 &quot;select &#39;put in&#39;&quot;으로 구금한다. 1인용 감옥, 족쇄, 노예 신분은 다른 상태다. Assassination은 은신 기절이며 Prisoner Pole도 구속 장치이지 영입 시설이 아니다. [S110, S113]</li><li><strong>[문서]</strong> 해방 후 도주/해방 거부/임시 추종/가입이 갈린다. 일부 고유 수감자는 즉시 가입하고 습격자는 포로를 풀어줄 수 있다. 감옥의 인물 despawn은 문서상 버그이므로 정상 탈출 확률로 취급하지 않는다. [S111, S112, S113]</li><li><strong>[적용 제안]</strong> B에서 생존·확보, S에서 후송, N에서 합류를 결정한다. 구금 중 전투·노동 조종권은 주지 않는다. [근거: S113, S120, S126]</li></ul><h3 id="_13-2-k-시스템-성격·자격·가해-기억-ref-k-prisoner-recruit" tabindex="-1">13.2 K-시스템: 성격·자격·가해 기억 [REF:K-PRISONER-RECRUIT] <a class="header-anchor" href="#_13-2-k-시스템-성격·자격·가해-기억-ref-k-prisoner-recruit" aria-label="Permalink to &quot;13.2 K-시스템: 성격·자격·가해 기억 [REF:K-PRISONER-RECRUIT]&quot;">​</a></h3><ul><li><strong>[문서: 원문]</strong> Slavery: &quot;Players cannot own their own slaves.&quot; 구매는 사유 노동력 소유가 아니라 해방 후 가입/이탈 가능성이 있는 경로다. [S110]</li><li><strong>[문서]</strong> 보편적인 감금→먹이기/치료→신뢰 게이지→가입 규칙이 아니다. 성격, 영입 가능한 대화 패키지, 모집 자격, 과거 납치·판매 기억이 문턱이다. 은인 재회 대화는 있지만 위키도 lifesaver 태그 생성 원인은 불확실하다고 적는다. [S111, S112, S115]</li><li><strong>[문서]</strong> Personality는 Honorable/Traitorous/Smart/Dumb/Brave/Fearful/Maniacal의 대화 태그다. Fearful/Dumb은 탈출을 꺼리고, Brave/Traitorous는 독자 탈출 경향, Smart/Honorable은 추종 가능 경로를 가진다. Shek/Hive Prince 예외가 있다. 위키의41%는 이미 따라온 인물의 조건부 후속 분기이지 모든 포로의 가입률이 아니다. [S111, S112]</li><li><strong>[문서]</strong> Playable Characters는 <code>max(STR,DEX)+max(MeleeAttack,MartialArts)+max(MeleeDefense,Dodge)&gt;=75</code>이면 일반 자격 불충족이며 Diplomat/Law Enforcer/Military/Trader를 제외한다고 적는다. Slavery의 STR+DEX+Toughness 요약과 충돌하고, 일부 대화는 자격 검사를 우회한다. FCS 직접 검증은 아니다. [S110, S115]</li><li><strong>[적용 제안]</strong> 성격을 숨은 성공률만으로 쓰지 않고 가족 보호·옛 동료 공격 거부·개인 원한 같은 합류 요구/거절 이유로 표현한다. 음식·치료만으로 가입을 보장하지 않는다. [근거: S111, S112, S115, S121]</li></ul><h3 id="_13-3-k-시스템-포로-경제와-중복-보상-ref-k-captive-economy" tabindex="-1">13.3 K-시스템: 포로 경제와 중복 보상 [REF:K-CAPTIVE-ECONOMY] <a class="header-anchor" href="#_13-3-k-시스템-포로-경제와-중복-보상-ref-k-captive-economy" aria-label="Permalink to &quot;13.3 K-시스템: 포로 경제와 중복 보상 [REF:K-CAPTIVE-ECONOMY]&quot;">​</a></h3><ul><li><strong>[문서]</strong> 일반 노예 인도400c, 별도 Rebirth 경로와 클래스 제약이 있다. 현상금은 해당 발행 세력에 생포 전액/사체 절반으로 정산한다. 노예 가격과 현상금은 모든 포로에게 자동 중첩되는 보상이 아니다. [S110, S114]</li><li><strong>[문서]</strong> 직접 판 사람에 대한 감사/모집 차단과 제3자 노예화로 책임 기억을 우회하는 사례, 반복 현상범 제출의 중복 돈/관계 버그가 문서화되어 있다. 특정 도망 노예 영입·발견은 Slave Capture 기지 공격의 계기가 된다. [S110, S111, S114]</li><li><strong>[추론]</strong> 즉시 수입 대 장기 인력 투자의 선택은 유효하지만 가해→구조 반복은 신뢰 파밍을 만든다. 원가해자·이관 이력·보상 소진이 필요하다. [S110, S111, S114]</li><li><strong>[적용 제안]</strong> 초기에는 노예 판매 시장 대신 계약된 현상금·인도·교환만 두고, 인물+의뢰 ID의 신병 이전/지급을1회 처리한다. [근거: S114, S123, S128]</li></ul><h3 id="_13-4-배너로드-일반병은-conformity-처리량이다-ref-mb-prisoner-recruit" tabindex="-1">13.4 배너로드: 일반병은 conformity 처리량이다 [REF:MB-PRISONER-RECRUIT] <a class="header-anchor" href="#_13-4-배너로드-일반병은-conformity-처리량이다-ref-mb-prisoner-recruit" aria-label="Permalink to &quot;13.4 배너로드: 일반병은 conformity 처리량이다 [REF:MB-PRISONER-RECRUIT]&quot;">​</a></h3><ul><li><strong>[문서]</strong> 제공 Capture prisoners는 classic 의뢰다. 구작의40%+Persuasion×4%, 캠프24시간, 사기-3을 Bannerlord 공식으로 인용하지 않는다. Companions는 주점 고용, Lords는 능력표여서 별도 모집 공식 근거가 필요하다. [S116, S117, S118]</li><li><strong>[문서]</strong> 공식 v1.2.12 API와 공개 역컴파일의 같은 버전 커밋 <code>d345b5dfc42b0fbb06b8b4b48b96486ed86d0d2f</code>를 읽었다. 공식 API는 선언만, 계수는 비공식 코드 아카이브다. 현재 모든 배포판의 공통 공식으로 보증하지 않는다. [S119, S120]</li><li><strong>[문서: 코드]</strong> 1명당 필요량 <code>K=(Level+6)^2-10</code>; 선택된 병종 묶음의 시간당 기본 증가 <code>10+0.05×Leadership</code>에 퍽 보정 후 반올림. 모집 가능 수는 <code>min(포로 수, floor(병종 XP/K))</code>. [S119]</li><li><strong>[문서]</strong> 매시간 무작위 시작점에서 미완료 일반병 묶음 <strong>하나만</strong> 증가한다. 포로 각각/모든 병종이 동시에 증가하지 않는다. 모집 확정 때 XP·포로 수를 줄이고 멤버 수를 늘린다. Hero는 일반병 모집 대상에서 제외한다. [S119, S120]</li><li><strong>[문서]</strong> Charm·개인 관계는 이 일반병 속도식의 직접 항이 아니다. 같은 문화+Presence 퍽은 모집 사기 손실 면제 조건이다. 일반-1/도적-2 사기와 Two Faced 도적 면제를 귀족 설득 확률과 혼합하지 않는다. [S119]</li><li><strong>[문서]</strong> 일반 blunt는 특수 치명 허용 플래그가 없으면 생존1을 반환한다. 다른 피해도 의료·레벨·Doctor&#39;s Oath 등으로 부상 생존 가능하다. &#39;둔기만 포로를 만든다&#39;는 일반화는 틀리다. [S122]</li><li><strong>[적용 제안]</strong> 잔선은 병종XP 대량 전환 대신 소수 인물의 자격·동의·계약을 선택한다. 포로/멤버 분리와 후송·정산 비용은 채택한다. [근거: S120, S126, S127]</li></ul><h3 id="_13-5-배너로드-귀족-포로의-가문-전향-ref-mb-lord-defection" tabindex="-1">13.5 배너로드: 귀족 포로의 가문 전향 [REF:MB-LORD-DEFECTION] <a class="header-anchor" href="#_13-5-배너로드-귀족-포로의-가문-전향-ref-mb-lord-defection" aria-label="Permalink to &quot;13.5 배너로드: 귀족 포로의 가문 전향 [REF:MB-LORD-DEFECTION]&quot;">​</a></h3><ul><li><strong>[문서: 원문]</strong> 포로 대사 &quot;join us, and be set free.&quot;의1.2.12 자격은 플레이어 왕국 지도자, 대상 가문 지도자, 현 군주 가문 제외, 플레이어 파티/소유 정착지 custody이며 전투 직후 CapturedLord/FreedHero 컨텍스트는 제외한다. &#39;귀족 포로는 절대 전향 불가&#39;도 틀리다. [S121]</li><li><strong>[문서]</strong> 신뢰·맹세·충성·정책·이익의 망설임을 논변으로 해소한다. 사용 skill/trait·논변 강도·관계와 사건 원장에 따라 옵션/성공·대성공·실패·대실패가 달라진다. 성공 뒤 별도의 가문 가입 barter가 필요할 수 있다. 실패한 동일 대상/망설임은1주 이내 재시도 제한이 있다. [S121]</li><li><strong>[문서]</strong> 몸값은 가문·재산·영지 수·퍽으로 산정하며, 귀족 탈출은 장소·호위 인원·퍽에 따른 일일 판정이다. 일반병 한도 초과의 시간당 탈출과 구별한다. 평화 석방과 처형의 가문/친구/세력/명예 비용도 별도다. [S123]</li><li><strong>[추론]</strong> 일반 포로 모집은 병력 전환, 귀족 전향은 정치 집단의 소속 변경이다. 같은 버튼/성공률로 설명하면 규모와 인과가 무너진다. [S119, S121, S123]</li><li><strong>[적용 제안]</strong> 잔선 주요 지도자는 일반 로스터 영입이 아니라 정치 사건 대상으로 둔다. 일반 직무 인물도 공석·소속 관계를 갱신하며 원세력 전체가 자동 아군이 되지 않는다. [근거: S121, S127]</li></ul><h3 id="_13-6-bb-포획이-없다는-전제의-예외-ref-bb-capture-exception" tabindex="-1">13.6 BB: 포획이 없다는 전제의 예외 [REF:BB-CAPTURE-EXCEPTION] <a class="header-anchor" href="#_13-6-bb-포획이-없다는-전제의-예외-ref-bb-capture-exception" aria-label="Permalink to &quot;13.6 BB: 포획이 없다는 전제의 예외 [REF:BB-CAPTURE-EXCEPTION]&quot;">​</a></h3><ul><li><strong>[문서: 원문]</strong> Game Guide의 모집은 &quot;In settlements for a fee&quot; / &quot;Via events for free&quot;다. 기본 비교는 고용 시장 중심이 맞지만 오직 도시 고용은 아니다. [S125]</li><li><strong>[문서: 원문]</strong> Manhunters 이벤트: &quot;You captured an Indebted after winning a battle&quot;. Blazing Deserts의 이 기원은 적격 인간전 승리/적 퇴각과 로스터 빈칸 조건에서 Indebted1명을 bad mood로 얻거나 거절한다. 전장 유닛의 능력·장비를 그대로 이전하는 범용 포획과는 다르다. [S124]</li><li><strong>[문서]</strong> 16명 출전/25명 보유, Indebted 비율 압박, 레벨7 상한·쓰러지면 사망 등이 함께 있다. 따라서 <strong>BB 전체에 적 포획 영입이 없다는 전제는 정정한다.</strong> [S124]</li><li><strong>[추론]</strong> 기본 고용 중심이면 고용비·일급·육성 손실을 독립적으로 가격화하고 도시 방문 이유를 유지하기 쉽다. 포획은 적과의 서사 연속성을 주지만 인력·장비·전리품 중복 보상과 상태 복잡성을 늘린다. 이는 해석이지 비공개 개발 의도를 확인한 주장이 아니다. [S124, S125, S126]</li></ul><h3 id="_13-7-잔선-b-확보-→-w-후송-→-n-합류-ref-js-capture-recruit" tabindex="-1">13.7 잔선: B 확보 → W 후송 → N 합류 [REF:JS-CAPTURE-RECRUIT] <a class="header-anchor" href="#_13-7-잔선-b-확보-→-w-후송-→-n-합류-ref-js-capture-recruit" aria-label="Permalink to &quot;13.7 잔선: B 확보 → W 후송 → N 합류 [REF:JS-CAPTURE-RECRUIT]&quot;">​</a></h3><p><strong>[적용 제안] 아래 숫자는 신규 밸런스 가설이지 구현 완료값이 아니다.</strong> 상세 상태 전이·탈출식·신뢰식·수용 시나리오는 보고서 §§11~20을 따른다. [근거: S126, S127, S128]</p><table tabindex="0"><thead><tr><th>면/단계</th><th>제안 규칙</th><th>근거</th></tr></thead><tbody><tr><td>B 제압</td><td>비살상 근접 명령 추가1AP 가설, HP0에서 안정된 쓰러짐. 치명 공격 중상자는 기한 내 응급처치로 생존 가능</td><td>[S113, S122, S128]</td></tr><tr><td>B 확보</td><td>확보1AP, 응급처치1AP+의료품1 가설. 마지막 적 후 전장 정리로 후송 선택 보장, 퇴각은 출구로 운반한 대상만</td><td>[S113, S120, S128]</td></tr><tr><td>W 후송</td><td>초기1자리 가설, 호송자·수레·식량 필요. 아군 부상자 후송과 경쟁, 확정 구간/숙영 사건에만 탈출 판정</td><td>[S123, S126, S128]</td></tr><tr><td>N 시설</td><td>자기 역 불필요, 우호 시설 사용권 필요. 치료/석방/계약 인도/수용/합류 조건 결정</td><td>[S110, S114, S123, S126]</td></tr><tr><td>N 합류</td><td>의식 회복+역할 이전+독립 이탈 이유+요구 해소+trust2 이상+동의+정원+계약비를 모두 요구</td><td>[S111, S115, S121, S127]</td></tr><tr><td>로스터</td><td>구금 종료/가입1회 처리, 부상·장비 보존. 약속 위반은 경고→갈등→재협상/이탈, 숨은 매일 배신 주사위 없음</td><td>[S120, S121, S125, S128]</td></tr></tbody></table><ul><li><strong>[적용 제안]</strong> trust는-3..+3 가설, 낯선 적 포획 직후-1. 적정 처우는 사건 전체+1 한도이고 보증/독립 약속 이행이 별도로 필요하다. 음식·치료 반복만으로 가입 문턱에 도달하지 못한다. 초기 설득은 조건 충족형이며 경비 강화는 탈출을 막지만 신뢰를 만들지 않는다. [근거: S110, S111, S114, S121]</li><li><strong>[문서]</strong> Starting-Presets는 Cast 인물을 프리셋별 필터로 무작위 시작 동료 배치한다고 적는다. 캠페인 후보 재추첨 세부 실행 규칙은 읽은 문서에서 확인되지 않았다. [S127]</li><li><strong>[적용 제안]</strong> 시작 추첨·N 일반 고용·B 포획·구조가 동일 PersonId 저장소와 공통 모집 자격/JoinRoster를 거친다. 수감/로스터 인물을 다른 역 후보나 적으로 중복 생성하지 않고 이름·능력·관계·과거를 보존한다. [근거: S120, S127, S128]</li><li><strong>[적용 제안]</strong> 원가해·이관 이력, 인물+현상금ID별 보상 소진, 목적별 RNG·사건 순번, 로스터/구금 소유권을 저장한다. 미리보기·메뉴 왕복·저장 로드는 시간/주사위를 진행하지 않는다. [근거: S110, S114, S128]</li><li><strong>[적용 제안]</strong> 노예 시장·노예 노동·범용 처형·매일 숨은 충성 주사위는 초기 비채택. 일반 고용을 유지하고 포획은 선택적 경로로 둔다. 감옥 보행이라는 네 번째 지도면은 만들지 않는다. [근거: S110, S121, S124, S125, S126]</li></ul><h3 id="_13-8-근거-한계-ref-capture-evidence-limits" tabindex="-1">13.8 근거 한계 [REF:CAPTURE-EVIDENCE-LIMITS] <a class="header-anchor" href="#_13-8-근거-한계-ref-capture-evidence-limits" aria-label="Permalink to &quot;13.8 근거 한계 [REF:CAPTURE-EVIDENCE-LIMITS]&quot;">​</a></h3><ul><li><strong>[문서]</strong> Bannerlord 수식은1.2.12 정적 자료다. 최신 HEAD에는 다른 모집 자격/해상 조건·문화 비교가 있어 혼합하지 않았다. K-시스템 FCS 전체 트리·41%의 버전 공통성은 직접 검증하지 않았다. [S112, S115, S119, S129]</li><li><strong>[문서]</strong> Workshop HTTP200 내부 요청 제한 오류, 일부 가이드404/403 및 빈 셸은 긍정 근거로 쓰지 않았다. [S129]</li><li><strong>[적용 제안]</strong> 제압/후송/가입/만원/거절/사망/탈출·저장 복원·중복 정산 방지를 향후 수용 시나리오로 제시했다. 잔선의 제안 수치와 실제 UI 동작은 아직 검증되지 않았다. [근거: S128, S129]</li></ul>',150)])])}const g=r(o,[["render",i]]);export{c as __pageData,g as default};
